import React, { Component, Fragment } from "react";
import { MDBDataTable, MDBBtn } from "mdbreact";
import { Card, CardBody, CardHeader, Button } from "reactstrap";

class Clients extends Component {
  state = {
    rowData: [
      {
        id: "Tiger Nixon",
        name: "System Architect",
        createdBy: "Edinburgh",
        actions: "61"
      },
      {
        id: "Garrett Winters",
        name: "Accountant",
        createdBy: "Tokyo",
        actions: (
          <MDBBtn color="purple" outline size="sm">
            Button
          </MDBBtn>
        )
      }
    ]
  };
  render() {
    const data = {
      columns: [
        {
          label: "Id",
          field: "id",
          sort: "asc"
        },
        {
          label: "Name",
          field: "name",
          sort: "asc"
        },
        {
          label: "CreatedBy",
          field: "createdBy",
          sort: "asc"
        },
        {
          label: "Actions",
          field: "actions",
          sort: "asc"
        }
      ],
      rows: this.state.rowData
    };

    return (
      <Card>
        <CardHeader>
          <h4>Clients</h4>
          <Button className="float-right" color="dark" onClick={this.toggle}>
            Add Item
          </Button>
        </CardHeader>
        <CardBody>
          <MDBDataTable striped bordered hover data={data} />
        </CardBody>
      </Card>
    );
  }
}
export default Clients;
